mapper.select:
SELECT id AS notification_id, category, notification_type AS notification_type, important, title, content, reference_type AS reference_type, reference_id AS reference_id, `read` AS is_read, created_at AS created_at FROM notification_histories WHERE user_id = #{userId}
AND id < #{cursor}
AND category = #{category}
ORDER BY id DESC LIMIT #{size}

SELECT EXISTS (
    SELECT 1
    FROM notification_histories
    WHERE id = #{notificationId}
      AND user_id = #{userId}
)

mapper.update:
UPDATE notification_histories
SET `read` = 1
WHERE id = #{notificationId}
  AND user_id = #{userId}

